"""Seed-0 RNG boundaries for the retained DA3-small and DA3-Base experiments.

The upstream constructors briefly create and discard native heads and several fusion
modules. Restoring the relevant boundaries preserves the retained initial weights
without vendoring those unused modules.
"""
import base64
import torch

_STATE_B64 = ""


def restore_reference_head_rng_state() -> None:
    raw = base64.b64decode(_STATE_B64)
    torch.set_rng_state(torch.tensor(list(raw), dtype=torch.uint8))


_DA3_BASE_HEAD_STATE_B64 = ""


def restore_da3_base_head_rng_state() -> None:
    """Restore the seed-0 state after DA3-Base's discarded native head."""
    raw = base64.b64decode(_DA3_BASE_HEAD_STATE_B64)
    torch.set_rng_state(torch.tensor(list(raw), dtype=torch.uint8))


_POSTFUSION_HEAD_STATE_B64 = ""
_POSTFUSION_VOXEL_ATTENTION_STATE_B64 = ""
_POSTFUSION_VOXEL_ENCODER_STATE_B64 = ""
_POSTFUSION_DEPTH_ATTENTION_STATE_B64 = ""


def restore_postfusion_rng_state(component: str) -> None:
    """Restore seed-0 state at a retained post-fusion module boundary."""
    states = {
        "head": _POSTFUSION_HEAD_STATE_B64,
        "voxel_attention": _POSTFUSION_VOXEL_ATTENTION_STATE_B64,
        "voxel_encoder": _POSTFUSION_VOXEL_ENCODER_STATE_B64,
        "depth_attention": _POSTFUSION_DEPTH_ATTENTION_STATE_B64,
    }
    try:
        encoded = states[component]
    except KeyError as error:
        raise ValueError(f"Unknown post-fusion RNG component: {component!r}.") from error
    raw = base64.b64decode(encoded)
    torch.set_rng_state(torch.tensor(list(raw), dtype=torch.uint8))
